const fs = require('node:fs');
const path = require('node:path');
const core = fs.readFileSync(path.join(__dirname, 'core.js'), 'utf8');
const source = fs.readFileSync(path.join(__dirname, 'main.source.js'), 'utf8');
const inlineCore = '(function () {\n' + core.replace('module.exports =', 'return') + '\n})();';
const bundled = source.replace("require('./core');", function () { return inlineCore; });
if (bundled.includes("require('./core')")) {
    throw new Error('Core module was not bundled');
}
fs.writeFileSync(path.join(__dirname, 'main.js'), '// Generated by build.cjs. Edit main.source.js and core.js.\n' + bundled, 'utf8');
console.log('Built self-contained Obsidian main.js (no relative runtime imports).');
